139→export const loader = async ({ request }: LoaderFunctionArgs) => {
140→  const { session } = await authenticate.admin(request);
141→  try {
142→    const [quizzes, templates] = await Promise.all([
143→      getQuizzes(session.shop),
144→      Promise.resolve(getTemplatesMeta()),
145→    ]);
146→    return { quizzes, templates };
147→  } catch {
148→    return { quizzes: [], templates: getTemplatesMeta() };
149→  }
150→};
