448→export default function MyQuizzes() {
449→  const { quizzes, templates } = useLoaderData<typeof loader>();
450→  const navigate = useNavigate();
451→  const submit = useSubmit();
452→
453→  // Fetcher is used exclusively for quiz creation so the page doesn't navigate
454→  // away during submission (the action returns a quizId we then navigate to).
455→  const fetcher = useFetcher<ActionResult>();
456→
457→  const [createMenuOpen, setCreateMenuOpen] = useState(false);
458→  const [modalOpen, setModalOpen] = useState(false);
459→  const [templateMode, setTemplateMode] = useState<"ai" | "direct">("ai");
460→  const [showAIOverlay, setShowAIOverlay] = useState(false);
461→  const [animationDone, setAnimationDone] = useState(false);
462→
463→  const isCreating = fetcher.state !== "idle";
464→  const showEmptyState = quizzes.length === 0;
465→
466→  // ── Navigate after creation ────────────────────────────────────────────────
467→  useEffect(() => {
468→    if (!fetcher.data) return;
469→
470→    if ("error" in fetcher.data) {
471→      showToast(String(fetcher.data.error), { isError: true });
472→      setShowAIOverlay(false);
473→      setAnimationDone(false);
474→      return;
475→    }
476→
477→    if ("quizId" in fetcher.data && fetcher.data.quizId) {
478→      const { quizId, message } = fetcher.data;
479→
480→      if (!showAIOverlay) {
481→        // Blank quiz — navigate immediately
482→        showToast(message ?? "Quiz created!");
483→        navigate(`/app/quizzes/${quizId}`);
484→      } else if (animationDone) {
