import db from "../db.server";

// ─── Helpers ──────────────────────────────────────────────────────────────────

function parseSafe<T>(value: string, fallback: T): T {
  try {
    return JSON.parse(value) as T;
  } catch {
    return fallback;
  }
}

/**
 * Wraps a CSV cell value: quotes the value if it contains commas, newlines, or
 * double-quotes. Double-quotes inside the value are escaped by doubling them.
 */
function csvCell(value: string): string {
  if (value.includes(",") || value.includes("\n") || value.includes('"')) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

function buildCsvRow(cells: string[]): string {
  return cells.map(csvCell).join(",");
}

// ─── Slug generation (mirrors quiz.server.ts) ─────────────────────────────────

function slugify(text: string): string {
  return (
    text
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, "")
      .replace(/\s+/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "") || "quiz"
  );
}

async function generateUniqueSlug(shop: string, title: string): Promise<string> {
  const base = slugify(title);
  let slug = base;
  let counter = 0;
  while (true) {
    const existing = await db.quiz.findFirst({ where: { shop, slug } });
    if (!existing) break;
    counter++;
    slug = `${base}-${counter}`;
  }
  return slug;
}

// ─── Export stats ─────────────────────────────────────────────────────────────

export async function getExportStats(
  shop: string
): Promise<{ quizCount: number; responseCount: number }> {
  const [quizCount, responseCount] = await Promise.all([
    db.quiz.count({ where: { shop, status: { not: "archived" } } }),
    db.quizResponse.count({ where: { shop } }),
  ]);
  return { quizCount, responseCount };
}

// ─── Export: quiz as JSON ─────────────────────────────────────────────────────

export async function exportQuizAsJson(
  quizId: string,
  shop: string
): Promise<object> {
  // Ownership check: always scope by shop
  const quiz = await db.quiz.findFirst({
    where: { id: quizId, shop },
    include: {
      questions: {
        include: { answers: { orderBy: { position: "asc" } } },
        orderBy: { position: "asc" },
      },
      resultPages: { orderBy: { position: "asc" } },
    },
  });

  if (!quiz) throw new Error("Quiz not found or access denied");

  // Strip DB-specific IDs — the export is portable across shops
  return {
    version: "1.0",
    exportedAt: new Date().toISOString(),
    quiz: {
      title: quiz.title,
      description: quiz.description ?? null,
      type: quiz.type,
      settings: parseSafe(quiz.settings, {}),
      styling: parseSafe(quiz.styling, {}),
      questions: quiz.questions.map((q) => ({
        type: q.type,
        title: q.title,
        description: q.description ?? null,
        imageUrl: q.imageUrl ?? null,
        required: q.required,
        position: q.position,
        settings: parseSafe(q.settings, {}),
        logic: parseSafe(q.logic, {}),
        answers: q.answers.map((a) => ({
          text: a.text,
          imageUrl: a.imageUrl ?? null,
          position: a.position,
          score: a.score,
          productTags: parseSafe(a.productTags, [] as string[]),
        })),
      })),
      resultPages: quiz.resultPages.map((rp) => ({
        title: rp.title,
        description: rp.description ?? null,
        type: rp.type,
        minScore: rp.minScore ?? null,
        maxScore: rp.maxScore ?? null,
        matchTags: parseSafe(rp.matchTags, [] as string[]),
        productLimit: rp.productLimit,
        layout: rp.layout,
        showDiscount: rp.showDiscount,
        discountType: rp.discountType ?? null,
        discountValue: rp.discountValue ?? null,
        discountCode: rp.discountCode ?? null,
        ctaText: rp.ctaText ?? null,
        ctaUrl: rp.ctaUrl ?? null,
        styling: parseSafe(rp.styling, {}),
        position: rp.position,
      })),
    },
  };
}

// ─── Export: responses as CSV ─────────────────────────────────────────────────

export async function exportResponsesAsCsv(
  quizId: string,
  shop: string
): Promise<string> {
  // Ownership check
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found or access denied");

  const responses = await db.quizResponse.findMany({
    where: { quizId, shop },
    orderBy: { createdAt: "desc" },
  });

  const headers = [
    "Response ID",
    "Email",
    "Score",
    "Recommended Products",
    "Completed At",
    "Source",
    "Device",
    "Created At",
  ];

  const rows = responses.map((r) => {
    const products = parseSafe(r.recommendedProducts, [] as string[]);
    return [
      r.id,
      r.email ?? "",
      String(r.score),
      products.join("; "),
      r.completedAt ? new Date(r.completedAt).toISOString() : "",
      r.source,
      r.deviceType ?? "",
      new Date(r.createdAt).toISOString(),
    ];
  });

  const lines = [
    buildCsvRow(headers),
    ...rows.map((row) => buildCsvRow(row)),
  ];

  return lines.join("\n");
}

// ─── Import: quiz from JSON ───────────────────────────────────────────────────

/**
 * Validated shape of an imported answer record.
 */
interface ImportedAnswer {
  text: string;
  imageUrl?: string | null;
  position?: number;
  score?: number;
  productTags?: string[];
}

/**
 * Validated shape of an imported question record.
 */
interface ImportedQuestion {
  type: string;
  title: string;
  description?: string | null;
  imageUrl?: string | null;
  required?: boolean;
  position?: number;
  settings?: Record<string, unknown>;
  logic?: Record<string, unknown>;
  answers?: ImportedAnswer[];
}

/**
 * Validated shape of an imported result page record.
 */
interface ImportedResultPage {
  title: string;
  description?: string | null;
  type?: string;
  minScore?: number | null;
  maxScore?: number | null;
  matchTags?: string[];
  productLimit?: number;
  layout?: string;
  showDiscount?: boolean;
  discountType?: string | null;
  discountValue?: number | null;
  discountCode?: string | null;
  ctaText?: string | null;
  ctaUrl?: string | null;
  styling?: Record<string, unknown>;
  position?: number;
}

/**
 * Validated shape of the top-level quiz import payload.
 */
interface ImportedQuizData {
  title: string;
  description?: string | null;
  type?: string;
  settings?: Record<string, unknown>;
  styling?: Record<string, unknown>;
  questions?: ImportedQuestion[];
  resultPages?: ImportedResultPage[];
}

/**
 * Expected wrapper envelope: { version, quiz: {...} }
 */
interface ImportEnvelope {
  version?: string;
  quiz: ImportedQuizData;
}

function assertString(value: unknown, field: string): string {
  if (typeof value !== "string" || value.trim() === "") {
    throw new Error(`Import validation failed: "${field}" must be a non-empty string`);
  }
  return value.trim();
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

function validateImportData(raw: unknown): ImportEnvelope {
  if (!isPlainObject(raw)) {
    throw new Error("Import data must be a JSON object");
  }

  // Support both envelope format { version, quiz } and bare quiz object
  const envelope = ("quiz" in raw && isPlainObject(raw.quiz))
    ? (raw as ImportEnvelope)
    : { quiz: raw as ImportedQuizData };

  const quizData = envelope.quiz;
  if (!isPlainObject(quizData)) {
    throw new Error('Import data must contain a "quiz" object');
  }

  assertString(quizData.title, "quiz.title");

  // Validate questions array if present
  if (quizData.questions !== undefined) {
    if (!Array.isArray(quizData.questions)) {
      throw new Error('"questions" must be an array');
    }
    quizData.questions.forEach((q: unknown, qi: number) => {
      if (!isPlainObject(q)) throw new Error(`questions[${qi}] must be an object`);
      assertString(q.type, `questions[${qi}].type`);
      assertString(q.title, `questions[${qi}].title`);
      if (q.answers !== undefined) {
        if (!Array.isArray(q.answers)) {
          throw new Error(`questions[${qi}].answers must be an array`);
        }
        q.answers.forEach((a: unknown, ai: number) => {
          if (!isPlainObject(a)) {
            throw new Error(`questions[${qi}].answers[${ai}] must be an object`);
          }
          assertString(a.text, `questions[${qi}].answers[${ai}].text`);
        });
      }
    });
  }

  // Validate resultPages array if present
  if (quizData.resultPages !== undefined) {
    if (!Array.isArray(quizData.resultPages)) {
      throw new Error('"resultPages" must be an array');
    }
    quizData.resultPages.forEach((rp: unknown, rpi: number) => {
      if (!isPlainObject(rp)) throw new Error(`resultPages[${rpi}] must be an object`);
      assertString(rp.title, `resultPages[${rpi}].title`);
    });
  }

  return envelope;
}

export async function importQuizFromJson(
  shop: string,
  quizData: unknown
): Promise<string> {
  const envelope = validateImportData(quizData);
  const q = envelope.quiz;

  const slug = await generateUniqueSlug(shop, q.title);

  const created = await db.quiz.create({
    data: {
      shop,
      title: q.title,
      slug,
      description: q.description ?? null,
      type: q.type ?? "product-recommendation",
      settings: JSON.stringify(q.settings ?? {}),
      styling: JSON.stringify(q.styling ?? {}),
      questions: {
        create: (q.questions ?? []).map((question: ImportedQuestion) => ({
          type: question.type,
          title: question.title,
          description: question.description ?? null,
          imageUrl: question.imageUrl ?? null,
          required: question.required ?? true,
          position: question.position ?? 0,
          settings: JSON.stringify(question.settings ?? {}),
          logic: JSON.stringify(question.logic ?? {}),
          answers: {
            create: (question.answers ?? []).map(
              (answer: ImportedAnswer) => ({
                text: answer.text,
                imageUrl: answer.imageUrl ?? null,
                position: answer.position ?? 0,
                score: answer.score ?? 0,
                productTags: JSON.stringify(answer.productTags ?? []),
              })
            ),
          },
        })),
      },
      resultPages: {
        create: (q.resultPages ?? []).map((rp: ImportedResultPage) => ({
          title: rp.title,
          description: rp.description ?? null,
          type: rp.type ?? "default",
          minScore: rp.minScore ?? null,
          maxScore: rp.maxScore ?? null,
          matchTags: JSON.stringify(rp.matchTags ?? []),
          productLimit: rp.productLimit ?? 4,
          layout: rp.layout ?? "grid",
          showDiscount: rp.showDiscount ?? false,
          discountType: rp.discountType ?? null,
          discountValue: rp.discountValue ?? null,
          discountCode: rp.discountCode ?? null,
          ctaText: rp.ctaText ?? null,
          ctaUrl: rp.ctaUrl ?? null,
          styling: JSON.stringify(rp.styling ?? {}),
          position: rp.position ?? 0,
        })),
      },
    },
    select: { id: true },
  });

  return created.id;
}

import { useState, useCallback } from "react";
import { data } from "react-router";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useLoaderData, useActionData, useFetcher } from "react-router";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Select,
  Button,
  ButtonGroup,
  Banner,
  TextField,
  Divider,
  Box,
  Badge,
  SkeletonPage,
  SkeletonBodyText,
} from "@shopify/polaris";
import { ExportIcon, ImportIcon } from "@shopify/polaris-icons";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import { getPlanId } from "../services/billing.server";
import { PLAN_FEATURES } from "../utils/constants";
import {
  exportQuizAsJson,
  exportResponsesAsCsv,
  importQuizFromJson,
  getExportStats,
} from "../services/export.server";
import { getQuizzes } from "../services/quiz.server";
import { showToast } from "../utils/toast";

// ─── Types ────────────────────────────────────────────────────────────────────

type QuizOption = {
  id: string;
  title: string;
  status: string;
  _count: { responses: number };
};

type LoaderData = {
  quizzes: QuizOption[];
  stats: { quizCount: number; responseCount: number };
  isPro: boolean;
  planId: string;
};

type ActionSuccess = {
  success: true;
  message: string;
  newQuizId?: string;
};

type ActionError = {
  error: string;
};

type ActionResult = ActionSuccess | ActionError;

// ─── Loader ───────────────────────────────────────────────────────────────────

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  try {
    const [quizzes, stats, planId] = await Promise.all([
      getQuizzes(shop),
      getExportStats(shop),
      getPlanId(shop),
    ]);

    const isPro = PLAN_FEATURES[planId].export;

    return {
      quizzes: quizzes.map((q) => ({
        id: q.id,
        title: q.title,
        status: q.status,
        _count: q._count,
      })),
      stats,
      isPro,
      planId,
    } satisfies LoaderData;
  } catch {
    return {
      quizzes: [],
      stats: { quizCount: 0, responseCount: 0 },
      isPro: false,
      planId: "free",
    } satisfies LoaderData;
  }
};

// ─── Action ───────────────────────────────────────────────────────────────────

export const action = async ({ request }: ActionFunctionArgs) => {
  // Law 1: auth first
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  // Law 13: plan gate — export requires Pro or higher
  const planId = await getPlanId(shop);
  if (!PLAN_FEATURES[planId].export) {
    return data<ActionResult>(
      { error: "Export requires the Pro plan or higher. Upgrade to access this feature." },
      { status: 403 }
    );
  }

  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    // ── Export JSON ───────────────────────────────────────────────────────────
    if (intent === "export-json") {
      const quizId = formData.get("quizId") as string;
      if (!quizId) {
        return data<ActionResult>({ error: "Please select a quiz to export." }, { status: 400 });
      }

      const exportData = await exportQuizAsJson(quizId, shop);
      const json = JSON.stringify(exportData, null, 2);
      const date = new Date().toISOString().slice(0, 10);

      return new Response(json, {
        headers: {
          "Content-Type": "application/json",
          "Content-Disposition": `attachment; filename="quiz-${quizId}-${date}.json"`,
        },
      });
    }

    // ── Export CSV ────────────────────────────────────────────────────────────
    if (intent === "export-csv") {
      const quizId = formData.get("quizId") as string;
      if (!quizId) {
        return data<ActionResult>({ error: "Please select a quiz to export responses for." }, { status: 400 });
      }

      const csv = await exportResponsesAsCsv(quizId, shop);
      const date = new Date().toISOString().slice(0, 10);

      return new Response(csv, {
        headers: {
          "Content-Type": "text/csv; charset=utf-8",
          "Content-Disposition": `attachment; filename="quiz-responses-${quizId}-${date}.csv"`,
        },
      });
    }

    // ── Import JSON ───────────────────────────────────────────────────────────
    if (intent === "import-json") {
      const jsonText = formData.get("jsonText") as string;
      if (!jsonText || jsonText.trim() === "") {
        return data<ActionResult>({ error: "Please paste quiz JSON before importing." }, { status: 400 });
      }

      let parsed: unknown;
      try {
        parsed = JSON.parse(jsonText);
      } catch {
        return data<ActionResult>(
          { error: "Invalid JSON. Please check the pasted text and try again." },
          { status: 400 }
        );
      }

      const newQuizId = await importQuizFromJson(shop, parsed);
      return data<ActionResult>({
        success: true,
        message: "Quiz imported successfully!",
        newQuizId,
      });
    }

    return data<ActionResult>({ error: "Unknown action." }, { status: 400 });
  } catch (error) {
    const message = error instanceof Error ? error.message : "An unexpected error occurred.";
    return data<ActionResult>({ error: message }, { status: 500 });
  }
};

// ─── HydrateFallback (skeleton) ───────────────────────────────────────────────

export function HydrateFallback() {
  return (
    <SkeletonPage title="Export & Import" backAction>
      <BlockStack gap="600">
        <Card>
          <SkeletonBodyText lines={6} />
        </Card>
        <Card>
          <SkeletonBodyText lines={5} />
        </Card>
      </BlockStack>
    </SkeletonPage>
  );
}

// ─── Page component ───────────────────────────────────────────────────────────

export default function ExportPage() {
  const { quizzes, stats, isPro, planId } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();

  // Separate fetchers so export-json and export-csv don't share state
  const exportFetcher = useFetcher<ActionResult>();
  const importFetcher = useFetcher<ActionResult>();

  const [selectedQuizId, setSelectedQuizId] = useState<string>(
    quizzes[0]?.id ?? ""
  );
  const [jsonText, setJsonText] = useState("");

  const isExporting = exportFetcher.state !== "idle";
  const isImporting = importFetcher.state !== "idle";

  // ── Toast feedback ──────────────────────────────────────────────────────────
  const importResult = importFetcher.data;

  if (importResult) {
    if ("success" in importResult && importResult.success) {
      showToast(importResult.message);
    } else if ("error" in importResult) {
      showToast(importResult.error, { isError: true });
    }
  }

  if (actionData) {
    if ("error" in actionData) {
      showToast(actionData.error, { isError: true });
    }
  }

  // ── Quiz selector options ───────────────────────────────────────────────────
  const quizSelectOptions = quizzes.map((q) => ({
    label: `${q.title} (${q._count.responses} response${q._count.responses !== 1 ? "s" : ""})`,
    value: q.id,
  }));

  // ── Export handlers — submit via exportFetcher so browser downloads the file
  const handleExportJson = useCallback(() => {
    if (!selectedQuizId) {
      showToast("Please select a quiz first.", { isError: true });
      return;
    }
    exportFetcher.submit(
      { intent: "export-json", quizId: selectedQuizId },
      { method: "POST" }
    );
  }, [exportFetcher, selectedQuizId]);

  const handleExportCsv = useCallback(() => {
    if (!selectedQuizId) {
      showToast("Please select a quiz first.", { isError: true });
      return;
    }
    exportFetcher.submit(
      { intent: "export-csv", quizId: selectedQuizId },
      { method: "POST" }
    );
  }, [exportFetcher, selectedQuizId]);

  const handleImport = useCallback(() => {
    if (!jsonText.trim()) {
      showToast("Please paste quiz JSON before importing.", { isError: true });
      return;
    }
    importFetcher.submit(
      { intent: "import-json", jsonText },
      { method: "POST" }
    );
  }, [importFetcher, jsonText]);

  const handleJsonTextChange = useCallback((value: string) => {
    setJsonText(value);
  }, []);

  // ── Plan gate ───────────────────────────────────────────────────────────────
  const upgradeBanner = !isPro && (
    <Banner
      title="Export & Import requires the Pro plan"
      tone="warning"
      action={{ content: "Upgrade to Pro", url: "/app/billing" }}
    >
      <p>
        You are on the <strong>{planId}</strong> plan. Upgrade to Pro ($29.99/mo)
        to unlock CSV response exports, JSON quiz backups, and quiz imports.
      </p>
    </Banner>
  );

  // ── Selected quiz info ──────────────────────────────────────────────────────
  const selectedQuiz = quizzes.find((q) => q.id === selectedQuizId);

  return (
    <Page
      title="Export & Import"
      backAction={{ content: "Back", url: "/app" }}
      subtitle="Download quiz data or import a quiz from a JSON backup"
    >
      <BlockStack gap="600">
        {/* Plan gate banner */}
        {upgradeBanner}

        {/* Stats strip */}
        <Card>
          <InlineStack gap="600" wrap>
            <BlockStack gap="100">
              <Text as="p" variant="bodySm" tone="subdued">
                Active quizzes
              </Text>
              <Text as="p" variant="headingLg" fontWeight="bold">
                {stats.quizCount}
              </Text>
            </BlockStack>
            <Box borderInlineStartWidth="025" borderColor="border" paddingInlineStart="600">
              <BlockStack gap="100">
                <Text as="p" variant="bodySm" tone="subdued">
                  Total responses
                </Text>
                <Text as="p" variant="headingLg" fontWeight="bold">
                  {stats.responseCount.toLocaleString()}
                </Text>
              </BlockStack>
            </Box>
          </InlineStack>
        </Card>

        <Layout>
          {/* ── Export section ──────────────────────────────────────────────── */}
          <Layout.Section>
            <Card>
              <BlockStack gap="500">
                <BlockStack gap="200">
                  <InlineStack gap="200" blockAlign="center">
                    <Text as="h2" variant="headingMd" fontWeight="semibold">
                      Export Quiz
                    </Text>
                    {!isPro && <Badge tone="warning">Pro</Badge>}
                  </InlineStack>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Download a quiz as a portable JSON backup, or export all
                    responses to a CSV spreadsheet.
                  </Text>
                </BlockStack>

                <Divider />

                {quizzes.length === 0 ? (
                  <Text as="p" variant="bodyMd" tone="subdued">
                    No quizzes found. Create a quiz first, then come back to
                    export it.
                  </Text>
                ) : (
                  <BlockStack gap="400">
                    <Select
                      label="Select quiz"
                      options={quizSelectOptions}
                      value={selectedQuizId}
                      onChange={setSelectedQuizId}
                      disabled={!isPro}
                    />

                    {selectedQuiz && (
                      <InlineStack gap="200" blockAlign="center">
                        <Text as="span" variant="bodySm" tone="subdued">
                          Status:
                        </Text>
                        <Badge
                          tone={
                            selectedQuiz.status === "active"
                              ? "success"
                              : selectedQuiz.status === "draft"
                                ? "attention"
                                : selectedQuiz.status === "paused"
                                  ? "warning"
                                  : undefined
                          }
                        >
                          {selectedQuiz.status.charAt(0).toUpperCase() +
                            selectedQuiz.status.slice(1)}
                        </Badge>
                        <Text as="span" variant="bodySm" tone="subdued">
                          {selectedQuiz._count.responses} response
                          {selectedQuiz._count.responses !== 1 ? "s" : ""}
                        </Text>
                      </InlineStack>
                    )}

                    <ButtonGroup>
                      <Button
                        icon={ExportIcon}
                        onClick={handleExportJson}
                        loading={isExporting}
                        disabled={!isPro || !selectedQuizId}
                      >
                        Export as JSON
                      </Button>
                      <Button
                        icon={ExportIcon}
                        onClick={handleExportCsv}
                        loading={isExporting}
                        disabled={!isPro || !selectedQuizId}
                      >
                        Export Responses (CSV)
                      </Button>
                    </ButtonGroup>

                    <Text as="p" variant="bodySm" tone="subdued">
                      JSON export includes all questions, answers, and result
                      pages — suitable for backup or migrating to another store.
                      CSV export includes every response record with email,
                      score, and recommended products.
                    </Text>
                  </BlockStack>
                )}
              </BlockStack>
            </Card>
          </Layout.Section>

          {/* ── Import section ──────────────────────────────────────────────── */}
          <Layout.Section>
            <Card>
              <BlockStack gap="500">
                <BlockStack gap="200">
                  <InlineStack gap="200" blockAlign="center">
                    <Text as="h2" variant="headingMd" fontWeight="semibold">
                      Import Quiz
                    </Text>
                    {!isPro && <Badge tone="warning">Pro</Badge>}
                  </InlineStack>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Paste the contents of a JSON export file to create a new
                    quiz from it. All questions, answers, and result pages will
                    be recreated. A unique slug will be generated automatically.
                  </Text>
                </BlockStack>

                <Divider />

                <BlockStack gap="400">
                  <TextField
                    label="Paste quiz JSON"
                    value={jsonText}
                    onChange={handleJsonTextChange}
                    multiline={10}
                    placeholder={`{\n  "version": "1.0",\n  "quiz": {\n    "title": "My Quiz",\n    ...\n  }\n}`}
                    disabled={!isPro}
                    autoComplete="off"
                    helpText='Paste the full contents of a ".json" file exported from QuizSnap.'
                  />

                  <Button
                    icon={ImportIcon}
                    variant="primary"
                    onClick={handleImport}
                    loading={isImporting}
                    disabled={!isPro || jsonText.trim() === ""}
                  >
                    Import Quiz
                  </Button>

                  {/* Import result feedback */}
                  {importResult && "success" in importResult && importResult.success && importResult.newQuizId && (
                    <Banner tone="success" title="Quiz imported successfully">
                      <p>
                        Your quiz has been created.{" "}
                        <a href={`/app/quizzes/${importResult.newQuizId}`}>
                          Open the quiz editor
                        </a>{" "}
                        to review and publish it.
                      </p>
                    </Banner>
                  )}

                  {importResult && "error" in importResult && (
                    <Banner tone="critical" title="Import failed">
                      <p>{importResult.error}</p>
                    </Banner>
                  )}
                </BlockStack>
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>
      </BlockStack>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

