  1→import db from "../db.server";
  2→
  3→// ─── Helpers ──────────────────────────────────────────────────────────────────
  4→
  5→function parseSafe<T>(value: string, fallback: T): T {
  6→  try {
  7→    return JSON.parse(value) as T;
  8→  } catch {
  9→    return fallback;
 10→  }
 11→}
 12→
 13→/**
 14→ * Wraps a CSV cell value: quotes the value if it contains commas, newlines, or
 15→ * double-quotes. Double-quotes inside the value are escaped by doubling them.
 16→ */
 17→function csvCell(value: string): string {
 18→  if (value.includes(",") || value.includes("\n") || value.includes('"')) {
 19→    return `"${value.replace(/"/g, '""')}"`;
 20→  }
 21→  return value;
 22→}
 23→
 24→function buildCsvRow(cells: string[]): string {
 25→  return cells.map(csvCell).join(",");
 26→}
 27→
 28→// ─── Slug generation (mirrors quiz.server.ts) ─────────────────────────────────
 29→
 30→function slugify(text: string): string {
 31→  return (
 32→    text
 33→      .toLowerCase()
 34→      .replace(/[^a-z0-9\s-]/g, "")
 35→      .replace(/\s+/g, "-")
 36→      .replace(/-+/g, "-")
 37→      .replace(/^-|-$/g, "") || "quiz"
 38→  );
 39→}
 40→
 41→async function generateUniqueSlug(shop: string, title: string): Promise<string> {
 42→  const base = slugify(title);
 43→  let slug = base;
 44→  let counter = 0;
 45→  while (true) {
 46→    const existing = await db.quiz.findFirst({ where: { shop, slug } });
 47→    if (!existing) break;
 48→    counter++;
 49→    slug = `${base}-${counter}`;
 50→  }
 51→  return slug;
 52→}
