 54→// ─── Export stats ─────────────────────────────────────────────────────────────
 55→
 56→export async function getExportStats(
 57→  shop: string
 58→): Promise<{ quizCount: number; responseCount: number }> {
 59→  const [quizCount, responseCount] = await Promise.all([
 60→    db.quiz.count({ where: { shop, status: { not: "archived" } } }),
 61→    db.quizResponse.count({ where: { shop } }),
 62→  ]);
 63→  return { quizCount, responseCount };
 64→}
