 66→// ─── Export: quiz as JSON ─────────────────────────────────────────────────────
 67→
 68→export async function exportQuizAsJson(
 69→  quizId: string,
 70→  shop: string
 71→): Promise<object> {
 72→  // Ownership check: always scope by shop
 73→  const quiz = await db.quiz.findFirst({
 74→    where: { id: quizId, shop },
 75→    include: {
 76→      questions: {
 77→        include: { answers: { orderBy: { position: "asc" } } },
 78→        orderBy: { position: "asc" },
 79→      },
 80→      resultPages: { orderBy: { position: "asc" } },
 81→    },
 82→  });
 83→
 84→  if (!quiz) throw new Error("Quiz not found or access denied");
 85→
 86→  // Strip DB-specific IDs — the export is portable across shops
 87→  return {
 88→    version: "1.0",
 89→    exportedAt: new Date().toISOString(),
 90→    quiz: {
 91→      title: quiz.title,
 92→      description: quiz.description ?? null,
 93→      type: quiz.type,
 94→      settings: parseSafe(quiz.settings, {}),
 95→      styling: parseSafe(quiz.styling, {}),
 96→      questions: quiz.questions.map((q) => ({
 97→        type: q.type,
 98→        title: q.title,
 99→        description: q.description ?? null,
100→        imageUrl: q.imageUrl ?? null,
101→        required: q.required,
102→        position: q.position,
103→        settings: parseSafe(q.settings, {}),
104→        logic: parseSafe(q.logic, {}),
105→        answers: q.answers.map((a) => ({
106→          text: a.text,
107→          imageUrl: a.imageUrl ?? null,
108→          position: a.position,
109→          score: a.score,
110→          productTags: parseSafe(a.productTags, [] as string[]),
111→        })),
112→      })),
113→      resultPages: quiz.resultPages.map((rp) => ({
114→        title: rp.title,
115→        description: rp.description ?? null,
116→        type: rp.type,
117→        minScore: rp.minScore ?? null,
118→        maxScore: rp.maxScore ?? null,
119→        matchTags: parseSafe(rp.matchTags, [] as string[]),
120→        productLimit: rp.productLimit,
121→        layout: rp.layout,
122→        showDiscount: rp.showDiscount,
123→        discountType: rp.discountType ?? null,
124→        discountValue: rp.discountValue ?? null,
125→        discountCode: rp.discountCode ?? null,
126→        ctaText: rp.ctaText ?? null,
127→        ctaUrl: rp.ctaUrl ?? null,
128→        styling: parseSafe(rp.styling, {}),
129→        position: rp.position,
130→      })),
131→    },
132→  };
133→}
