135→// ─── Export: responses as CSV ─────────────────────────────────────────────────
136→
137→export async function exportResponsesAsCsv(
138→  quizId: string,
139→  shop: string
140→): Promise<string> {
141→  // Ownership check
142→  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
143→  if (!quiz) throw new Error("Quiz not found or access denied");
144→
145→  const responses = await db.quizResponse.findMany({
146→    where: { quizId, shop },
147→    orderBy: { createdAt: "desc" },
148→  });
149→
150→  const headers = [
151→    "Response ID",
152→    "Email",
153→    "Score",
154→    "Recommended Products",
155→    "Completed At",
156→    "Source",
157→    "Device",
158→    "Created At",
159→  ];
160→
161→  const rows = responses.map((r) => {
162→    const products = parseSafe(r.recommendedProducts, [] as string[]);
163→    return [
164→      r.id,
165→      r.email ?? "",
166→      String(r.score),
167→      products.join("; "),
168→      r.completedAt ? new Date(r.completedAt).toISOString() : "",
169→      r.source,
170→      r.deviceType ?? "",
171→      new Date(r.createdAt).toISOString(),
172→    ];
173→  });
174→
175→  const lines = [
176→    buildCsvRow(headers),
177→    ...rows.map((row) => buildCsvRow(row)),
178→  ];
179→
180→  return lines.join("\n");
181→}
