183→// ─── Import: quiz from JSON ───────────────────────────────────────────────────
184→
185→/**
186→ * Validated shape of an imported answer record.
187→ */
188→interface ImportedAnswer {
189→  text: string;
190→  imageUrl?: string | null;
191→  position?: number;
192→  score?: number;
193→  productTags?: string[];
194→}
195→
196→/**
197→ * Validated shape of an imported question record.
198→ */
199→interface ImportedQuestion {
200→  type: string;
201→  title: string;
202→  description?: string | null;
203→  imageUrl?: string | null;
204→  required?: boolean;
205→  position?: number;
206→  settings?: Record<string, unknown>;
207→  logic?: Record<string, unknown>;
208→  answers?: ImportedAnswer[];
209→}
210→
211→/**
212→ * Validated shape of an imported result page record.
213→ */
214→interface ImportedResultPage {
215→  title: string;
216→  description?: string | null;
217→  type?: string;
218→  minScore?: number | null;
219→  maxScore?: number | null;
220→  matchTags?: string[];
221→  productLimit?: number;
222→  layout?: string;
223→  showDiscount?: boolean;
224→  discountType?: string | null;
225→  discountValue?: number | null;
226→  discountCode?: string | null;
227→  ctaText?: string | null;
228→  ctaUrl?: string | null;
229→  styling?: Record<string, unknown>;
230→  position?: number;
231→}
232→
233→/**
234→ * Validated shape of the top-level quiz import payload.
235→ */
236→interface ImportedQuizData {
237→  title: string;
238→  description?: string | null;
239→  type?: string;
240→  settings?: Record<string, unknown>;
241→  styling?: Record<string, unknown>;
242→  questions?: ImportedQuestion[];
243→  resultPages?: ImportedResultPage[];
244→}
245→
246→/**
247→ * Expected wrapper envelope: { version, quiz: {...} }
248→ */
249→interface ImportEnvelope {
250→  version?: string;
251→  quiz: ImportedQuizData;
252→}
253→
254→function assertString(value: unknown, field: string): string {
255→  if (typeof value !== "string" || value.trim() === "") {
256→    throw new Error(`Import validation failed: "${field}" must be a non-empty string`);
257→  }
258→  return value.trim();
259→}
260→
261→function isPlainObject(v: unknown): v is Record<string, unknown> {
262→  return typeof v === "object" && v !== null && !Array.isArray(v);
263→}
264→
265→function validateImportData(raw: unknown): ImportEnvelope {
266→  if (!isPlainObject(raw)) {
267→    throw new Error("Import data must be a JSON object");
268→  }
269→
270→  // Support both envelope format { version, quiz } and bare quiz object.
271→  // Cast through unknown so TS strict mode accepts the narrowing.
272→  const envelope = ("quiz" in raw && isPlainObject(raw.quiz))
273→    ? (raw as unknown as ImportEnvelope)
274→    : ({ quiz: raw as unknown as ImportedQuizData } satisfies ImportEnvelope);
275→
276→  const quizData = envelope.quiz;
277→  if (!isPlainObject(quizData)) {
278→    throw new Error('Import data must contain a "quiz" object');
279→  }
280→
281→  assertString(quizData.title, "quiz.title");
282→
283→  // Validate questions array if present
284→  if (quizData.questions !== undefined) {
285→    if (!Array.isArray(quizData.questions)) {
286→      throw new Error('"questions" must be an array');
287→    }
288→    quizData.questions.forEach((q: unknown, qi: number) => {
289→      if (!isPlainObject(q)) throw new Error(`questions[${qi}] must be an object`);
290→      assertString(q.type, `questions[${qi}].type`);
291→      assertString(q.title, `questions[${qi}].title`);
292→      if (q.answers !== undefined) {
293→        if (!Array.isArray(q.answers)) {
294→          throw new Error(`questions[${qi}].answers must be an array`);
295→        }
296→        q.answers.forEach((a: unknown, ai: number) => {
297→          if (!isPlainObject(a)) {
298→            throw new Error(`questions[${qi}].answers[${ai}] must be an object`);
299→          }
300→          assertString(a.text, `questions[${qi}].answers[${ai}].text`);
301→        });
302→      }
303→    });
304→  }
305→
306→  // Validate resultPages array if present
307→  if (quizData.resultPages !== undefined) {
308→    if (!Array.isArray(quizData.resultPages)) {
309→      throw new Error('"resultPages" must be an array');
310→    }
311→    quizData.resultPages.forEach((rp: unknown, rpi: number) => {
312→      if (!isPlainObject(rp)) throw new Error(`resultPages[${rpi}] must be an object`);
313→      assertString(rp.title, `resultPages[${rpi}].title`);
314→    });
315→  }
316→
317→  return envelope;
318→}
319→
320→export async function importQuizFromJson(
321→  shop: string,
322→  quizData: unknown
323→): Promise<string> {
324→  const envelope = validateImportData(quizData);
325→  const q = envelope.quiz;
326→
327→  const slug = await generateUniqueSlug(shop, q.title);
328→
329→  const created = await db.quiz.create({
330→    data: {
331→      shop,
332→      title: q.title,
333→      slug,
334→      description: q.description ?? null,
335→      type: q.type ?? "product-recommendation",
336→      settings: JSON.stringify(q.settings ?? {}),
337→      styling: JSON.stringify(q.styling ?? {}),
338→      questions: {
339→        create: (q.questions ?? []).map((question: ImportedQuestion) => ({
340→          type: question.type,
341→          title: question.title,
342→          description: question.description ?? null,
343→          imageUrl: question.imageUrl ?? null,
344→          required: question.required ?? true,
345→          position: question.position ?? 0,
346→          settings: JSON.stringify(question.settings ?? {}),
347→          logic: JSON.stringify(question.logic ?? {}),
348→          answers: {
349→            create: (question.answers ?? []).map(
350→              (answer: ImportedAnswer) => ({
351→                text: answer.text,
352→                imageUrl: answer.imageUrl ?? null,
353→                position: answer.position ?? 0,
354→                score: answer.score ?? 0,
355→                productTags: JSON.stringify(answer.productTags ?? []),
356→              })
357→            ),
358→          },
359→        })),
360→      },
361→      resultPages: {
362→        create: (q.resultPages ?? []).map((rp: ImportedResultPage) => ({
363→          title: rp.title,
364→          description: rp.description ?? null,
365→          type: rp.type ?? "default",
366→          minScore: rp.minScore ?? null,
367→          maxScore: rp.maxScore ?? null,
368→          matchTags: JSON.stringify(rp.matchTags ?? []),
369→          productLimit: rp.productLimit ?? 4,
370→          layout: rp.layout ?? "grid",
371→          showDiscount: rp.showDiscount ?? false,
372→          discountType: rp.discountType ?? null,
373→          discountValue: rp.discountValue ?? null,
374→          discountCode: rp.discountCode ?? null,
375→          ctaText: rp.ctaText ?? null,
376→          ctaUrl: rp.ctaUrl ?? null,
377→          styling: JSON.stringify(rp.styling ?? {}),
378→          position: rp.position ?? 0,
379→        })),
380→      },
381→    },
382→    select: { id: true },
383→  });
384→
385→  return created.id;
386→}
